-- composition of rule kernels limit_pushdown x window_self_join (duckdb), template union
SELECT count(*) FROM (SELECT 1 AS k FROM (SELECT COALESCE ((EXISTS (SELECT 10.0::numeric AS c0, 1::bigint AS c1)), TRUE) AS c0 FROM tp AS a1) AS ka UNION ALL SELECT 2 AS k FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 100.0::float8 AS c1, '0'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, 100.0::float8 AS c1, MAX ('-1 month'::interval) OVER () AS c2 FROM tp AS a1) AS kb) AS u;
